//! Tensorhub's client: generated by progenitor from the Hub's own API document (`openapi.yaml`,
//! pinned in `SOURCE`), with the credentials every cozy process speaks as: a user's device-key
//! login and Bearer, a run's DPoP-bound token traded from its capability, a pod's worker
//! capability. Bulk bytes (presigned GET/PUT) are not here: TensorFS moves them.
mod auth;
mod device;
mod jws;
mod raw;
mod run;
#[cfg(feature = "testing")]
pub mod testing;

#[allow(clippy::all, unused_imports)]
mod generated {
    include!(concat!(env!("OUT_DIR"), "/hub.rs"));
}

pub use auth::{Auth, Credential};
pub use device::{Bearer, DeviceKey, Enrollment, RunCapability, UserSession};
pub use generated::{Client, types};
pub use jws::{P256Key, leaf_thumbprint, thumbprint};
pub use progenitor_client::{ByteStream, ResponseValue};

/// A generated call's own error, before it is read as an [`Error`].
pub type CallError = progenitor_client::Error<types::Error>;
pub use run::{Ended, Op, RunToken};

/// A refused or failed call. `Hub` carries the Hub's own typed refusal verbatim.
#[derive(Debug, thiserror::Error)]
pub enum Error {
    #[error("{code}: {message}")]
    Hub {
        status: u16,
        code: String,
        message: String,
        remedy: String,
    },
    #[error("Tensorhub: {0}")]
    Call(String),
    /// The call's credential could not be had (a login failed); nothing was sent.
    #[error("{0}")]
    Credential(String),
    #[error("an unusable answer: {0}")]
    Answer(String),
    #[error("key: {0}")]
    Key(String),
    #[error("{0}")]
    Capability(String),
    #[error(transparent)]
    Ended(#[from] Ended),
}

impl<E: serde::Serialize + std::fmt::Debug> From<progenitor_client::Error<E>> for Error {
    fn from(error: progenitor_client::Error<E>) -> Self {
        if let progenitor_client::Error::ErrorResponse(answer) = &error {
            let status = answer.status().as_u16();
            let body = serde_json::to_value(answer.as_ref()).unwrap_or_default();
            let field = |name: &str| body["error"][name].as_str().unwrap_or_default().to_string();
            if !field("code").is_empty() {
                return Self::Hub {
                    status,
                    code: field("code"),
                    message: field("message"),
                    remedy: field("remedy"),
                };
            }
            if let Some(code) = body["error"].as_str() {
                let message = body["error_description"]
                    .as_str()
                    .unwrap_or_default()
                    .to_string();
                return Self::Hub {
                    status,
                    code: code.to_string(),
                    message,
                    remedy: String::new(),
                };
            }
        }
        match error {
            progenitor_client::Error::Custom(why) => Self::Credential(why),
            other => Self::Call(other.to_string()),
        }
    }
}
